package com.healthsystem.config;
import io.swagger.v3.oas.annotations.media.Schema;
import java.util.*;
/** OpenAPI views for JSON-preserving task workflow bodies. Runtime validates presence and ownership. */
public final class TaskApiDocumentationModels {
 private TaskApiDocumentationModels(){}
 @Schema(name="TaskRevisionRequest") public record Revision(@Schema(requiredMode=Schema.RequiredMode.REQUIRED,description="任务包rowVersion；生成任务包时为来源方案rowVersion",example="0") String expectedRevision){}
 @Schema(name="TaskBundlePatchRequest") public record BundlePatch(@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String expectedRevision,@Schema(description="必须包含当前包全部任务组；省略的组内字段保持原值") List<GroupPatch> groups){}
 public record GroupPatch(@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String id,ScheduleRule schedule,@Schema(allowableValues={"REQUIRED","OPTIONAL"}) String taskClass,@Schema(allowableValues={"L0","L1","L2","L3","L4"}) String priorityCode,Boolean safetyFocus,Boolean executionConfirmed,String confirmationNote,String displayNote){}
 public record ScheduleRule(List<Integer> isoWeekdays,List<Slot> slots,@Schema(allowableValues={"FIXED","ROTATE"}) String rotationPolicy,List<String> variantKeys,Integer minRestDays,Boolean activeInputRequired){}
 public record Slot(String slotKey,@Schema(allowableValues={"FIXED"},description="本轮不支持ANCHOR") String mode,@Schema(example="08:00") String localTime,Integer opensOffsetMinutes,Integer closesOffsetMinutes,Integer normalCutoffOffsetMinutes){}
 @Schema(name="TaskReviewRequest") public record TaskReview(@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String expectedRevision,@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String schedulePreviewId){}
 @Schema(name="TaskNewVersionRequest") public record NewVersion(@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String expectedRevision,@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String changeReason){}
 @Schema(name="PublicationPreviewRequest") public record PublicationIntent(@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String expectedRevision,@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String reviewSubmissionId,@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String schedulePreviewId,@Schema(requiredMode=Schema.RequiredMode.REQUIRED,example="2026-10-17T00:00:00Z") String effectiveAt,@Schema(requiredMode=Schema.RequiredMode.REQUIRED,allowableValues={"NONE","ALL_FUTURE"}) String replacementScope){}
 @Schema(name="PublicationRequest") public record PublicationRequest(@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String expectedRevision,@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String reviewSubmissionId,@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String schedulePreviewId,@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String effectiveAt,@Schema(requiredMode=Schema.RequiredMode.REQUIRED,allowableValues={"NONE","ALL_FUTURE"}) String replacementScope,@Schema(requiredMode=Schema.RequiredMode.REQUIRED) String publicationPreviewId){}
 @Schema(name="CheckInRequest",description="所有字段选填，空对象默认患者自述完成；不能提供评分或服务器接收时间")
 public record Feedback(@Schema(allowableValues={"COMPLETED","PARTIAL","NOT_DONE","STOPPED"},defaultValue="COMPLETED") String completion,String actualExecutedAt,Boolean reportedSafety,String note,String reason,String feeling,Map<String,Object> values){}
 @Schema(name="FeedbackAmendmentRequest",description="最新反馈的追加更正；省略字段保留，null清空可选反馈")
 public record Amendment(@Schema(requiredMode=Schema.RequiredMode.REQUIRED,description="任务currentResult.rowVersion") String expectedRevision,@Schema(allowableValues={"COMPLETED","PARTIAL","NOT_DONE","STOPPED"}) String completion,String actualExecutedAt,Boolean reportedSafety,String note,String reason,String feeling,Map<String,Object> values){}
 @Schema(name="TaskGroupView") public record Group(String id,String dimensionCode,String actorType,String title,String taskClass,String priorityCode,Boolean safetyFocus,String evaluationMode,String basicGoal,String action,String planGoal,List<String> sourcePlanItemIds,List<String> sourceFactIds,List<String> sourceModuleCodes,Map<String,Object> template,Map<String,Object> professionalBinding,Map<String,Object> feedbackSchema,List<String> generationIssues,Boolean executionConfirmed,String confirmationNote,ScheduleRule schedule,List<Variant> variants){}
 public record Variant(String id,String variantKey,String title,String content,Map<String,Object> parameters){}
 public record ContentSnapshot(String ruleVersion,String sourcePlanVersionId,String sourceReviewSubmissionId,String sourceReviewDecisionId,String sourceContentHash,Group group,Variant variant){}
 public record Occurrence(String occurrenceKey,String groupId,String variantId,String dimensionCode,String executionDate,String zoneId,String slotKey,String plannedAt,String opensAt,String closesAt,String normalCutoffAt,String makeupCutoffAt,ContentSnapshot contentSnapshot,String taskClass,String priorityCode,Boolean safetyFocus,Boolean activeInputRequired){}
 public record PublicationView(String id,String patientId,String taskBundleId,String reviewSubmissionId,String schedulePreviewId,String publicationPreviewId,String effectiveAt,String status,String notificationStatus,Long taskCount){}
 public record PublicationPreviewView(String id,String taskBundleId,String expectedRevision,String reviewSubmissionId,String schedulePreviewId,String effectiveAt,String replacementScope,String previewHash,List<String> createOccurrenceKeys,List<String> replaceTaskIds,List<String> retainTaskIds){}
 public record Assessment(String completion,Integer completionRatio,String executionTiming,String submissionSource,String feedbackCompleteness,String qualityStatus,String qualityUnavailableReason,String safetyStatus,Boolean selfReported){}
 public record CurrentResult(String rowVersion,String currentFeedbackId,Assessment assessment,String updatedAt){}
 public record ExecutionView(String id,String patientId,String publicationId,String taskBundleId,String occurrenceKey,String dimensionCode,String executionDate,String zoneId,String slotKey,String plannedAt,String opensAt,String closesAt,String normalCutoffAt,String makeupCutoffAt,ContentSnapshot contentSnapshot,String taskClass,String priorityCode,Boolean safetyFocus,String scheduledCancellationAt,CurrentResult currentResult){}
 public record FeedbackView(String id,String executionTaskId,String previousFeedbackId,Integer versionNo,String resultRevision,Feedback body,Assessment assessment,String receivedAt,String submittedBy){}
}
